<template>
  <div v-if="showPage">
    <el-button
      type="primary"
      plain
      icon="el-icon-plus"
      size="mini"
      @click="addRules"
      >新增规则</el-button
    >
    <el-table class="mt-10" :data="ruleList" style="width: 100%">
      <el-table-column label="序号">
        <template slot-scope="scope">{{ scope.$index + 1 }}</template>
      </el-table-column>
      <el-table-column prop="scene_name" label="场景名称"> </el-table-column>
      <el-table-column label="操作">
        <template slot-scope="scope">
          <el-button type="text" @click="association(scope.row)">
            <i title="配置" class="el-icon-setting"></i>
          </el-button>
          <el-button
            type="text"
            icon="el-icon-edit"
            @click="editData(scope.row)"
          />
          <el-button type="text" @click="delData(scope.row)">
            <i title="删除" class="el-icon-delete" style="color: red"></i>
          </el-button>
        </template>
      </el-table-column>
    </el-table>
    <el-dialog
      :title="title"
      :visible.sync="addVisible"
      width="50%"
      :close-on-click-modal="false"
      top="10px"
      :rules="rules"
    >
      <el-form :model="addForm" ref="addForm" label-width="120px" class="mt-20">
        <el-form-item label="场景名称:" prop="scene_name">
          <el-input v-model="addForm.scene_name" style="width: 60%"></el-input>
        </el-form-item>
        <el-form-item label="场景状态:" prop="scene_status">
          <el-radio-group v-model="addForm.scene_status">
            <el-radio :label="0">禁用 </el-radio>
            <el-radio :label="1">启用</el-radio>
          </el-radio-group>
        </el-form-item>
        <el-form-item label="触发类型:" prop="trigger_type">
          <el-select v-model="addForm.trigger_type">
            <el-option label="设备触发" :value="1"></el-option>
            <el-option label="定时触发" :value="2"></el-option>
          </el-select>
        </el-form-item>
        <el-form-item
          label="cron表达式:"
          prop="trigger_cron"
          v-if="addForm.trigger_type == 2"
        >
          <el-input
            v-model="addForm.trigger_cron"
            style="width: 80%"
          ></el-input>
          <el-button type="text" class="ml-10" @click="CronVisible = true"
            >生成表达式</el-button
          >
        </el-form-item>

        <el-form-item label="延迟执行:" prop="execute_delay">
          <el-input-number
            v-model="addForm.execute_delay"
            class="mr-10"
          ></el-input-number
          >(秒)
        </el-form-item>
      </el-form>
      <span slot="footer" class="dialog-footer">
        <el-button @click="addVisible = false">取 消</el-button>
        <el-button type="primary" @click="submitForm('addForm')"
          >确 定</el-button
        >
      </span>
    </el-dialog>
    <el-dialog
      title="Cron表达式生成器"
      :visible.sync="CronVisible"
      width="50%"
      :close-on-click-modal="false"
      top="10px"
    >
      <Crontab @fill="fill" @hide="CronVisible = false" />
    </el-dialog>
  </div>
  <div v-else class="configure">
    <el-page-header @back="showPage = true" :content="configure.scene_name">
    </el-page-header>
    <el-divider content-position="left">执行条件</el-divider>
    <el-form :model="conditionForm" inline size="small" class="mb-30">
      <el-form-item>
        逻辑操作：
        <el-radio-group v-model="logical">
          <el-radio :label="1">与</el-radio>
          <el-radio :label="2">或</el-radio>
        </el-radio-group>
      </el-form-item>
      <div class="condition mt-10" v-if="conditionForm.conditions.length == 0">
        <el-empty description="暂无数据" :image-size="50"></el-empty>
      </div>
      <div
        class="condition mt-10"
        v-for="(item, index) in conditionForm.conditions"
        :key="index"
      >
        <div class="header">
          <div>
            <i class="el-icon-arrow-down"></i> #{{ index + 1 }}.执行条件
          </div>
          <i
            class="el-icon-delete"
            style="color: red"
            @click="delTerm('conditions', index)"
          ></i>
        </div>
        <div class="p-10">
          <el-row :gutter="10">
            <el-col :span="4">
              <el-form-item>
                <el-select v-model="item.cond_type" placeholder="条件类型">
                  <el-option label="属性状态" :value="1"></el-option>
                  <el-option label="告警状态" :value="2"></el-option>
                </el-select>
              </el-form-item>
            </el-col>
            <el-col :span="5">
              <el-form-item>
                <el-select
                  v-model="item.source_id"
                  @change="changeSource($event, item)"
                  placeholder="请选择采集源"
                >
                  <el-option
                    v-for="source in sourceList"
                    :key="source.source_id"
                    :label="source.source_name"
                    :value="source.source_id"
                  ></el-option>
                </el-select>
              </el-form-item>
            </el-col>
            <el-col :span="5">
              <el-form-item>
                <el-select
                  v-model="item.pro_id"
                  placeholder="请选择属性"
                  @visible-change="getProperty($event, item)"
                >
                  <el-option
                    v-for="pro in propertyList"
                    :key="pro.pro_id"
                    :label="pro.describe"
                    :value="pro.pro_id"
                  ></el-option>
                </el-select>
              </el-form-item>
            </el-col>
            <template v-if="item.cond_type == 1">
              <el-col :span="5">
                <el-form-item>
                  <el-select v-model="item.compare_mode" placeholder="比较模式">
                    <el-option
                      v-for="(c, i) in comparison"
                      :key="i"
                      :label="c"
                      :value="i + 1"
                    ></el-option>
                  </el-select>
                </el-form-item>
              </el-col>
              <el-col :span="5">
                <el-form-item>
                  <el-input
                    v-model="item.cond_value"
                    placeholder="请输入条件值"
                  ></el-input>
                </el-form-item>
              </el-col>
            </template>
            <el-col :span="5" v-else>
              <el-form-item>
                <el-select v-model="item.cond_value" placeholder="条件类型">
                  <el-option label="告警" value="1"></el-option>
                  <el-option label="消警" value="0"></el-option>
                </el-select>
              </el-form-item>
            </el-col>
          </el-row>
        </div>
      </div>
      <el-button
        type="primary"
        icon="el-icon-plus"
        size="mini"
        class="mb-20 mt-20"
        @click="addTerm('conditions')"
        plain
        >添加执行条件</el-button
      >
      <el-divider content-position="left">执行动作</el-divider>
      <div class="condition mt-10" v-if="conditionForm.actions.length == 0">
        <el-empty description="暂无数据" :image-size="50"></el-empty>
      </div>
      <div
        class="condition"
        v-for="(item, index) in conditionForm.actions"
        :key="index + 'actions'"
      >
        <div class="header">
          <div>
            <i class="el-icon-arrow-down"></i> #{{ index + 1 }}.执行动作
          </div>
          <i
            class="el-icon-delete"
            style="color: red"
            @click="delTerm('actions', index)"
          ></i>
        </div>
        <div class="p-10">
          <el-row :gutter="20">
            <el-col :span="6">
              <el-form-item>
                <el-select
                  v-model="item.action_type"
                  placeholder="请选择执行动作类型"
                >
                  <el-option label="属性设置" :value="1"></el-option>
                </el-select>
              </el-form-item>
            </el-col>
            <el-col :span="6">
              <el-form-item>
                <el-select
                  v-model="item.source_id"
                  @change="changeSource($event, item)"
                  placeholder="请选择采集源"
                >
                  <el-option
                    v-for="source in sourceList"
                    :key="source.source_id"
                    :label="source.source_name"
                    :value="source.source_id"
                  ></el-option>
                </el-select>
              </el-form-item>
            </el-col>
            <el-col :span="6">
              <el-form-item>
                <el-select
                  v-model="item.pro_id"
                  placeholder="请选择属性"
                  @visible-change="getProperty($event, item)"
                >
                  <el-option
                    v-for="pro in propertyList"
                    :key="pro.pro_id"
                    :label="pro.describe"
                    :value="pro.pro_id"
                  ></el-option>
                </el-select>
              </el-form-item>
            </el-col>
            <el-col :span="6">
              <el-form-item>
                <el-input
                  v-model="item.action_value"
                  placeholder="请输入执行动作值"
                ></el-input>
              </el-form-item>
            </el-col>
          </el-row>
        </div>
      </div>
      <el-button
        type="primary"
        icon="el-icon-plus"
        size="mini"
        @click="addTerm('actions')"
        plain
        >添加执行动作</el-button
      >
    </el-form>
    <el-button type="primary" @click="submitConditionForm" size="small"
      >提交</el-button
    >
    <el-button @click="reset" size="small">重置</el-button>
  </div>
</template>

<script>
import Crontab from "@/components/Crontab/index.vue";
export default {
  components: {
    Crontab,
  },
  data() {
    return {
      ruleList: [],
      addForm: {},
      addVisible: false,
      title: "新增规则",
      rules: {},
      showPage: true,
      configure: {},
      conditionForm: {
        conditions: [],
        actions: [],
        del_conditions: [],
        del_actions: [],
      },
      sourceList: [],
      propertyList: [],
      logical: 1,
      comparison: [">", " >=", "<", "<=", "==", "!="],
      CronVisible: false,
    };
  },
  created() {
    this.getData();
    this.getSourceList();
  },
  methods: {
    fill(e) {
      this.addForm.trigger_cron = e;
    },
    reset() {
      this.getRulesConditionList();
    },
    submitConditionForm() {
      this.conditionForm.conditions.forEach((item) => {
        item.logical_operation = this.logical;
      });
      this.$api
        .post("/rules/saveRulesConditionAndAction", {
          scene_id: this.configure.scene_id,
          ...this.conditionForm,
        })
        .then(() => {
          this.$message.success("操作成功");
          this.getRulesConditionList();
        });
    },
    getProperty(e, item) {
      console.log(e);
      console.log(item);
      if (e) this.changeSource(item.source_id);
    },
    changeSource(e, item) {
      if (item) {
        item.pro_id = "";
      }
      this.propertyList = [];
      this.$api
        .get(`/collect/getDataPropertyList`, { params: { source_id: e } })
        .then((res) => {
          if (res.data.data) {
            this.propertyList = res.data.data;
          }
        });
    },
    getSourceList() {
      this.$api.get(`/collect/getDataSourceList`).then((res) => {
        if (res.data.data) {
          this.sourceList = res.data.data;
        }
      });
    },
    getRulesConditionList() {
      this.conditionForm = {
        conditions: [],
        actions: [],
        del_conditions: [],
        del_actions: [],
      };
      this.$api
        .get(`/rules/getRulesConditionList`, {
          params: { scene_id: this.configure.scene_id },
        })
        .then((res) => {
          if (res.data.data) {
            this.conditionForm.conditions = res.data.data;
            this.logical = this.conditionForm.conditions[0].logical_operation;
            this.conditionForm.conditions.forEach((item) => {
              this.changeSource(item.source_id);
            });
          }
        });
      this.$api
        .get(`/rules/getRulesActionList`, {
          params: { scene_id: this.configure.scene_id },
        })
        .then((res) => {
          if (res.data.data) {
            this.conditionForm.actions = res.data.data;
            this.conditionForm.actions.forEach((item) => {
              this.changeSource(item.source_id);
            });
          }
        });
    },
    getData() {
      this.$api.get(`/rules/getRulesList`).then((res) => {
        if (res.data.data) {
          this.ruleList = res.data.data;
        }
      });
    },
    delTerm(termType, index) {
      let arr = [...this.conditionForm[termType]];
      let delItem = arr
        .slice(index, index + 1)
        .filter((item) => item.cond_id || item.action_id)[0];
      if (delItem)
        this.conditionForm[`del_${termType}`].push(
          termType == "actions"
            ? { action_id: delItem.action_id }
            : { cond_id: delItem.cond_id }
        );
      this.conditionForm[termType].splice(index, 1);

      console.log(this.conditionForm);
    },
    addTerm(termType) {
      this.conditionForm[termType].push(
        termType == "actions" ? {} : { compare_mode: 5 }
      );
    },
    editData(item) {
      this.title = "编辑场景";
      this.addForm = { ...item };
      this.addVisible = true;
    },
    association(item) {
      this.configure = item;
      this.showPage = false;
      this.getRulesConditionList();
    },
    delData(item) {
      this.$confirm("是否删除该数据?", "提示", {
        confirmButtonText: "确定",
        cancelButtonText: "取消",
        type: "warning",
      })
        .then(() => {
          this.$api
            .post("/rules/delRules", {
              scene_id: item.scene_id,
            })
            .then(() => {
              this.$message.success("操作成功");
              this.getData();
            });
        })
        .catch(() => {
          this.$message({
            type: "info",
            message: "已取消删除",
          });
        });
    },
    submitForm(formName) {
      if (this.addForm.trigger_type == 1) {
        this.addForm.trigger_cron = undefined;
      }
      this.$refs[formName].validate((valid) => {
        if (valid) {
          let url = this.addForm.scene_id
            ? "/rules/updateRules"
            : "/rules/addRules";
          this.$api.post(url, this.addForm).then(() => {
            this.addVisible = false;
            this.$message.success("操作成功");
            this.getData();
          });
        } else {
          return false;
        }
      });
    },
    addRules() {
      this.title = "新增场景";
      this.addForm = {};
      this.addVisible = true;
    },
  },
};
</script>

<style lang="scss" scoped>
::v-deep .el-page-header__content {
  font-size: 16px !important;
}

.configure {
  ::v-deep .el-form-item--small {
    margin-bottom: 0 !important;
    width: 100% !important;
  }
}
::v-deep .el-form-item--small .el-form-item__content {
  width: 100% !important;
}
::v-deep .condition {
  border: 1px solid #e4e4e4;
  margin-bottom: 10px;
  .el-select {
    width: 100%;
  }
  .header {
    background: #fafafa;
    padding: 10px;
    display: flex;
    justify-content: space-between;
    border-bottom: 1px solid #e4e4e4;
    font-size: 14px;
  }
}
</style>
